import Foundation
import TildeCore

/// Access to the key fixtures generated by `generate-fixtures.sh` (real `ssh-keygen` / OpenSSL output).
enum Fixtures {
    static let passphrase = "tilde-test-passphrase"

    static var directory: URL {
        Bundle.module.resourceURL!.appendingPathComponent("Fixtures", isDirectory: true)
    }

    static func data(_ name: String) throws -> Data {
        try Data(contentsOf: directory.appendingPathComponent(name))
    }

    static func text(_ name: String) throws -> String {
        try String(contentsOf: directory.appendingPathComponent(name), encoding: .utf8)
    }

    /// The `SHA256:...` fingerprint recorded from `ssh-keygen -lf` for the fixture `<name>.fp` (or `<name>` + suffix).
    static func fingerprint(_ fpFile: String) throws -> String {
        let line = try text(fpFile).split(separator: "\n").first.map(String.init) ?? ""
        let tokens = line.split(separator: " ")
        return String(tokens[1])
    }

    /// The first two tokens (`type base64`) of the `.pub` fixture.
    static func publicKeyCore(_ pubFile: String) throws -> String {
        let tokens = try text(pubFile).split(whereSeparator: { $0 == " " || $0 == "\n" })
        return tokens[0] + " " + tokens[1]
    }

    /// The randomart block of a `.art` file (everything after the fingerprint line).
    static func randomart(_ artFile: String) throws -> String {
        try text(artFile).split(separator: "\n", omittingEmptySubsequences: false).dropFirst().joined(separator: "\n")
            .trimmingCharacters(in: .newlines)
    }

    /// (fixture name, algorithm) pairs for the six `ssh-keygen`-generated key types.
    static let sshKeygenKeys: [(name: String, algorithm: SSHKeyAlgorithm)] = [
        ("ed25519", .ed25519), ("ecdsa256", .ecdsaP256), ("ecdsa384", .ecdsaP384),
        ("ecdsa521", .ecdsaP521), ("rsa3072", .rsa), ("rsa4096", .rsa),
    ]
}

/// Runs the system `ssh-keygen` (macOS only) for cross-checks. Returns `nil` when it is unavailable.
enum SSHKeygen {
    static var isAvailable: Bool {
        #if os(macOS)
        FileManager.default.isExecutableFile(atPath: "/usr/bin/ssh-keygen")
        #else
        false
        #endif
    }

    /// Runs `ssh-keygen` with `arguments` and returns stdout, or `nil` on a non-zero exit.
    static func run(_ arguments: [String]) -> String? {
        #if os(macOS)
        let process = Process()
        process.executableURL = URL(fileURLWithPath: "/usr/bin/ssh-keygen")
        process.arguments = arguments
        let pipe = Pipe()
        process.standardOutput = pipe
        process.standardError = Pipe()
        do { try process.run() } catch { return nil }
        let output = pipe.fileHandleForReading.readDataToEndOfFile()
        process.waitUntilExit()
        guard process.terminationStatus == 0 else { return nil }
        return String(decoding: output, as: UTF8.self)
        #else
        return nil
        #endif
    }

    /// Writes `data` to a private temp file (mode 0600), runs `body`, and deletes the file.
    static func withTempKeyFile<T>(_ data: Data, _ body: (String) throws -> T) throws -> T {
        let url = FileManager.default.temporaryDirectory.appendingPathComponent("tilde-test-\(UUID().uuidString)")
        try data.write(to: url, options: .atomic)
        try FileManager.default.setAttributes([.posixPermissions: 0o600], ofItemAtPath: url.path)
        defer { try? FileManager.default.removeItem(at: url) }
        return try body(url.path)
    }
}
